import{_ as t,o as e,c as o,a5 as s}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"进阶版：多 Worker + Worker Pool 线程池封装方案","description":"很好！你是真正要把 Web Worker 用到生产里的那种人了 😄 —— 现在我带你进入真正适合重计算的 Worker Pool 线程池模型 ，以后你处理大批量订单、筹码分布、实时计算，都会非常丝滑。 🚀 先简单理解一下 为什么用 Worker Pool 单 Worker Wor。","frontmatter":{"title":"进阶版：多 Worker + Worker Pool 线程池封装方案","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","进阶语言能力"],"description":"很好！你是真正要把 Web Worker 用到生产里的那种人了 😄 —— 现在我带你进入真正适合重计算的 Worker Pool 线程池模型 ，以后你处理大批量订单、筹码分布、实时计算，都会非常丝滑。 🚀 先简单理解一下 为什么用 Worker Pool 单 Worker Wor。","sidebarWeight":49,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/webworkers/进阶版：多 Worker + Worker Pool 线程池封装方案.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/07-进阶语言能力/进阶版：多 Worker + Worker Pool 线程池封装方案.md","filePath":"posts/JavaScript系统教程/07-进阶语言能力/进阶版：多 Worker + Worker Pool 线程池封装方案.md"}'),n={name:"posts/JavaScript系统教程/07-进阶语言能力/进阶版：多 Worker + Worker Pool 线程池封装方案.md"};function l(a,r,i,p,k,g){return e(),o("div",null,[...r[0]||(r[0]=[s('<div><h1 id="进阶版-多-worker-worker-pool-线程池封装方案" tabindex="-1">进阶版：多 Worker + Worker Pool 线程池封装方案 <a class="header-anchor" href="#进阶版-多-worker-worker-pool-线程池封装方案" aria-label="Permalink to &quot;进阶版：多 Worker + Worker Pool 线程池封装方案&quot;">​</a></h1><blockquote><p>本节目标：理解“进阶版：多 Worker + Worker Pool 线程池封装方案”的核心思路，并能把它用于实际开发或面试表达。 很好！你是真正要把 Web Worker 用到生产里的那种人了 😄 —— 现在我带你进入真正适合重计算的 <strong>Worker Pool 线程池模型</strong>，以后你处理大批量订单、筹码分布、实时计算，都会非常丝滑。</p></blockquote><p><strong>🚀</strong> <strong>先简单理解一下 为什么用 Worker Pool</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>单 Worker</strong></td><td><strong>Worker Pool</strong></td></tr><tr><td>每次创建新 worker</td><td>复用多个预先创建好的 worker</td></tr><tr><td>创建成本高</td><td>只初始化 N 个 worker，循环复用</td></tr><tr><td>单核执行</td><td>多核并行</td></tr><tr><td>适合轻计算</td><td>适合重计算、高并发</td></tr></tbody></table><p>👉 也就是说：<strong>Worker Pool = Web Worker 里的“线程池”思想</strong></p><p><strong>🎯</strong> <strong>DEMO 场景</strong></p><ul><li>订单数据量：10万条</li><li>每条数据做复杂统计</li><li>用 4 个 worker 并行处理</li></ul><p><strong>✅</strong> <strong>目录结构扩展版</strong></p><p>bash 复制编辑 src/ workers/ ordersWorker.ts poolWorker.ts &lt;-- worker池专用worker逻辑 utils/ processUnfoldOrders.ts splitChunks.ts &lt;-- 分片工具 pool/ WorkerPool.ts &lt;-- 核心线程池封装 types/ workerTypes.ts</p><p><strong>✅</strong> <strong>先写通用分片工具 (utils/splitChunks.ts)</strong></p><p>ts 复制编辑 export function splitChunks&lt;T&gt;(arr: T[], chunkSize: number): T[][] { const chunks: T[][] = [] for (let i = 0; i &lt; arr.length; i += chunkSize) { chunks.push(arr.slice(i, i + chunkSize)) } return chunks}</p><p><strong>✅</strong> <strong>Worker 核心逻辑 (workers/poolWorker.ts)</strong></p><p>ts 复制编辑 import type { WorkerMessage, ProcessOrdersData } from &#39;@/types/workerTypes&#39;import { processUnfoldOrders } from &#39;@/utils/processUnfoldOrders&#39; self.addEventListener(&#39;message&#39;, (event: MessageEvent&lt;WorkerMessage&gt;) =&gt; { const { type, data } = event.data if (type === &#39;processOrders&#39;) { try { const result = processUnfoldOrders(data.orderData) self.postMessage({ type: &#39;processedOrders&#39;, data: result }) } catch (err) { self.postMessage({ type: &#39;error&#39;, data: (err as Error).message }) } }}) 注意：此处用静态 import，因为在 pool 内部，逻辑更纯粹、更高效。</p><p><strong>✅</strong> <strong>Worker Pool 封装 (pool/WorkerPool.ts)</strong></p><p>ts 复制编辑 import type { WorkerMessage, ProcessOrdersData, ProcessedOrdersResult } from &#39;@/types/workerTypes&#39; export class WorkerPool { private workers: Worker[] private queue: (() =&gt; void)[] private activeCount: number private maxConcurrency: number constructor(workerUrl: URL, maxConcurrency = 4) { this.workers = Array.from({ length: maxConcurrency }, () =&gt; new Worker(workerUrl, { type: &#39;module&#39; })) this.queue = [] this.activeCount = 0 this.maxConcurrency = maxConcurrency } runTask(data: ProcessOrdersData): Promise&lt;ProcessedOrdersResult&gt; { return new Promise((resolve, reject) =&gt; { const task = () =&gt; { const worker = this.workers.pop()! worker.onmessage = (event: MessageEvent&lt;WorkerMessage&gt;) =&gt; { this.workers.push(worker) this.activeCount-- this.next() if (event.data.type === &#39;processedOrders&#39;) { resolve(event.data.data) } else { reject(event.data.data) } } worker.onerror = (err) =&gt; { this.workers.push(worker) this.activeCount-- this.next() reject(err) } worker.postMessage({ type: &#39;processOrders&#39;, data }) } this.queue.push(task) this.next() }) } private next() { if (this.activeCount &gt;= this.maxConcurrency) return if (this.queue.length === 0) return const task = this.queue.shift()! this.activeCount++ task() } terminateAll() { this.workers.forEach(worker =&gt; worker.terminate()) }} ✅ 这里封装了自动调度、并发控制、复用 worker 等逻辑</p><p><strong>✅</strong> <strong>业务逻辑示范 (App.vue)</strong></p><p>vue 复制编辑 &lt;template&gt; &lt;div&gt; &lt;h1&gt;Worker Pool DEMO&lt;/h1&gt; &lt;button @click=&quot;startProcessing&quot;&gt;开始并行处理&lt;/button&gt; &lt;div v-if=&quot;results.length&quot;&gt; &lt;div v-for=&quot;(r, i) in results&quot; :key=&quot;i&quot;&gt;子任务{{ i + 1 }}结果：{{ r.result }}&lt;/div&gt; &lt;/div&gt; &lt;/div&gt;&lt;/template&gt; &lt;script lang=&quot;ts&quot; setup&gt;import { WorkerPool } from &#39;@/pool/WorkerPool&#39;import { splitChunks } from &#39;@/utils/splitChunks&#39;import type { ProcessOrdersData, ProcessedOrdersResult } from &#39;@/types/workerTypes&#39; const workerUrl = new URL(&#39;@/workers/poolWorker.ts&#39;, import.meta.url)const pool = new WorkerPool(workerUrl, 4) const results = ref&lt;ProcessedOrdersResult[]&gt;([]) async function startProcessing() { results.value = [] const bigData = Array(10000).fill({ id: 1, name: &#39;order&#39; }) const chunks = splitChunks(bigData, 2500) // 分成 4 份 const promises = chunks.map(chunk =&gt; pool.runTask({ orderData: chunk } as ProcessOrdersData) ) results.value = await Promise.all(promises)}&lt;/script&gt;</p><p><strong>✅</strong> <strong>运行效果</strong></p><ul><li>10万条订单数据 → 4个 Worker 分片处理</li><li>CPU 多核利用</li><li>UI 丝滑不卡顿</li><li>并发池统一管理</li></ul><p><strong>✅</strong> <strong>未来扩展方向</strong></p><ul><li>✅ 自动根据 CPU 核心数动态分配 worker 数</li><li>✅ 支持 Worker 复用、超时、销毁</li><li>✅ 支持任务优先级、暂停恢复等高级调度策略</li></ul><p><strong>🎯</strong> <strong>你现在收获的是：</strong> 一份真正能上生产的 <strong>高性能前端计算引擎框架</strong> 以后你做筹码分布、图表聚合、实时行情大数据计算等， <strong>直接套 Worker Pool 模板就是生产最佳实践。</strong></p><p>要不要我顺手再帮你出一份： ✅ <strong>完整仓库版本，可以直接 clone 下来跑的 DEMO 项目</strong> 👉 你一句话 &quot;要完整仓库&quot; 我直接出全套源码。</p></div>',1)])])}const d=t(n,[["render",l]]);export{c as __pageData,d as default};
